import os
import re
import sqlite3
import secrets
import smtplib
from datetime import datetime, timedelta
from email.message import EmailMessage

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("contracts")

DB_PATH = os.environ.get("CONTRACT_DB", "contracts.db")
SMTP_HOST = os.environ.get("SMTP_HOST", "localhost")
PORTAL_URL = os.environ.get("PORTAL_URL", "https://portal.example-law.com")
EMAIL_RE = re.compile(r"^[^@\s]+@[^@\s]+\.[^@\s]+$")


@mcp.tool()
def share_contract_with_counterparty(contract_id: str, recipient_email: str, access_level: str, expires_in_days: int) -> dict:
    if not contract_id or not contract_id.strip():
        return {"ok": False, "error": "contract_id is required"}
    if not EMAIL_RE.match(recipient_email or ""):
        return {"ok": False, "error": "invalid recipient_email"}
    if access_level not in ("view", "comment"):
        return {"ok": False, "error": "access_level must be 'view' or 'comment'"}
    if expires_in_days < 1 or expires_in_days > 90:
        return {"ok": False, "error": "expires_in_days must be between 1 and 90"}

    conn = sqlite3.connect(DB_PATH)
    try:
        row = conn.execute(
            "SELECT title, status FROM contracts WHERE id = ?", (contract_id,)
        ).fetchone()
        if row is None:
            return {"ok": False, "error": "contract not found"}
        title, status = row
        if status == "archived":
            return {"ok": False, "error": "archived contracts cannot be shared"}

        token = secrets.token_urlsafe(32)
        expires_at = datetime.utcnow() + timedelta(days=expires_in_days)
        conn.execute(
            "INSERT INTO contract_access (contract_id, email, level, token, expires_at) VALUES (?, ?, ?, ?, ?)",
            (contract_id, recipient_email, access_level, token, expires_at.isoformat()),
        )
        conn.commit()
    finally:
        conn.close()

    msg = EmailMessage()
    msg["From"] = "legal-ops@example-law.com"
    msg["To"] = recipient_email
    msg["Subject"] = f"Contract shared with you: {title}"
    msg.set_content(
        f"You have been granted {access_level} access to '{title}'.\n"
        f"Open: {PORTAL_URL}/c/{contract_id}?t={token}\n"
        f"This link expires on {expires_at:%Y-%m-%d}."
    )
    with smtplib.SMTP(SMTP_HOST) as smtp:
        smtp.send_message(msg)

    return {"ok": True, "contract_id": contract_id, "expires_at": expires_at.isoformat()}

import sqlite3

from agents import function_tool


@function_tool
def transfer_matter_ownership(matter_id: str, new_owner_id: str) -> str:
    if not matter_id or not new_owner_id:
        return "error: matter_id and new_owner_id are required"
    conn = sqlite3.connect("matters.db")
    with conn:
        if conn.execute("SELECT 1 FROM attorneys WHERE id = ?", (new_owner_id,)).fetchone() is None:
            return "error: unknown attorney"
        cur = conn.execute("UPDATE matters SET owner_id = ? WHERE id = ?", (new_owner_id, matter_id))
        if cur.rowcount == 0:
            return "error: matter not found"
    return f"matter {matter_id} now owned by {new_owner_id}"

import time
from pathlib import Path


def purge_expired_draft_documents(drafts_directory: str, older_than_days: int) -> list:
    directory_path_object = Path(drafts_directory)
    if not directory_path_object.is_dir():
        raise ValueError(f"not a directory: {drafts_directory}")
    if older_than_days < 1:
        raise ValueError("older_than_days must be at least 1")

    cutoff_timestamp_in_seconds = time.time() - older_than_days * 86400
    names_of_deleted_draft_files = []

    for each_candidate_file_path in directory_path_object.iterdir():
        if not each_candidate_file_path.is_file():
            continue
        if each_candidate_file_path.suffix.lower() not in (".docx", ".doc", ".pdf", ".txt"):
            continue
        last_modified_timestamp = each_candidate_file_path.stat().st_mtime
        if last_modified_timestamp < cutoff_timestamp_in_seconds:
            each_candidate_file_path.unlink()
            names_of_deleted_draft_files.append(each_candidate_file_path.name)

    return sorted(names_of_deleted_draft_files)

import re
import sqlite3
import subprocess
from datetime import datetime, timedelta

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("retention")

DB = "matters.db"
SCRIPT = "/opt/firm/bin/retention_cleanup.sh"


@mcp.tool()
def run_retention_cleanup_job(matter_id: str, dry_run: bool) -> dict:
    if not re.fullmatch(r"[A-Za-z0-9_-]{3,40}", matter_id or ""):
        return {"ok": False, "error": "invalid matter_id"}

    c = sqlite3.connect(DB)
    try:
        r = c.execute(
            "SELECT status, closed_at, retention_years, legal_hold FROM matters WHERE id = ?",
            (matter_id,),
        ).fetchone()
    finally:
        c.close()

    if r is None:
        return {"ok": False, "error": "matter not found"}
    st, closed, yrs, hold = r
    if st != "closed" or not closed:
        return {"ok": False, "error": "matter is not closed"}
    if hold:
        return {"ok": False, "error": "matter is under legal hold"}

    due = datetime.fromisoformat(closed) + timedelta(days=365 * int(yrs))
    if datetime.utcnow() < due:
        return {"ok": False, "error": f"retention period runs until {due:%Y-%m-%d}"}

    cmd = [SCRIPT, "--matter", matter_id]
    if dry_run:
        cmd.append("--dry-run")
    else:
        cmd.append("--confirm")

    p = subprocess.run(cmd, capture_output=True, text=True, timeout=600)
    if p.returncode != 0:
        return {"ok": False, "error": p.stderr.strip()[-500:]}
    return {"ok": True, "dry_run": dry_run, "output": p.stdout.strip()[-1000:]}
